actions.script:
accepted = false; duplicate = false; reasonCode = null; outcomeList = []
const refuse = (code, message) => { reasonCode = code; ec.message.addError(message) }
ec.artifactExecution.disableAuthz()
const bridge = ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', chatBridgeId).one()
if (!bridge) { refuse('unknownBridge', 'Unknown chat bridge'); return }
if (bridge.statusId === 'CbsDisabled') { refuse('bridgeDisabled', 'The chat bridge is disabled'); return }
const check = ec.service.sync().name('org.moqui.impl.ChatBridgeServices.check#BridgeToken')
        .parameters({chatBridgeId: chatBridgeId, token: token || ''}).call()
if (!check || check.valid !== true) { refuse('badToken', 'The chat bridge token does not match'); return }
if (!/^[A-Za-z0-9_.:-]{1,128}$/.test(String(transactionId || ''))) { refuse('badTransaction', 'A transaction id is up to 128 letters, digits and _ . : -'); return }
const items = Array.from(itemList || [])
let batchJson
try { batchJson = JSON.stringify(items) } catch (err) { refuse('batchTooLarge', 'The batch cannot be read'); return }
if (items.length > 200 || batchJson.length > 1048576) { refuse('batchTooLarge', 'A batch is at most 200 items and 1 MB'); return }
// an adapter never acts as a local account: an item that names a local user is a security failure
const LOCAL_KEYS = ['userId', 'senderUserId', 'localUserId', 'chatActorId', 'senderActorId']
if (items.some((item) => item && typeof item === 'object' && LOCAL_KEYS.some((key) => item[key] != null))) {
    refuse('localIdentity', 'An item from a bridge may not name a local user'); return }

// stored before it is acknowledged; a transaction sent before is not worked again
ec.message.pushErrors()
let stored = null
try {
    stored = ec.service.sync().name('org.moqui.impl.ChatBridgeServices.store#Inbound').parameters({chatBridgeId: chatBridgeId,
        transactionId: transactionId, batchJson: batchJson, itemCount: items.length}).requireNewTransaction(true).call()
} catch (err) { ec.logger.warn(`Chat bridge ${chatBridgeId} transaction ${transactionId}: ${err && err.message ? err.message : err}`) }
const storeFailed = ec.message.hasError()
ec.message.clearErrors()
ec.message.popErrors()
const row = ec.entity.find('moqui.chat.ChatBridgeInbound').condition('chatBridgeId', chatBridgeId).condition('transactionId', transactionId).one()
if (!row) { ec.message.addError(`Could not store chat bridge transaction ${transactionId}`); return }
duplicate = storeFailed || !stored || stored.created !== true
accepted = true
// a transaction sent before answers its outcomes so far (an item not yet worked is waiting): one still being
// worked by the first call, or left by a stop, is the first call's or the worker's (process#PendingInbound)
if (duplicate || row.statusEnumId === 'CbiDone') {
    outcomeList = ec.service.sync().name('org.moqui.impl.ChatBridgeServices.get#InboundOutcomes').parameters({chatBridgeId: chatBridgeId,
        transactionId: transactionId}).call()?.outcomeList || []
    return
}
const worked = ec.service.sync().name('org.moqui.impl.ChatBridgeServices.process#Inbound').parameters({chatBridgeId: chatBridgeId,
    transactionId: transactionId, followUp: true}).call()
outcomeList = (worked && worked.outcomeList) || []

outcomeList = []
const row = ec.entity.find('moqui.chat.ChatBridgeInbound').condition('chatBridgeId', chatBridgeId).condition('transactionId', transactionId)
        .disableAuthz().one()
if (!row) return
const parse = (text, empty) => { try { return text ? JSON.parse(text) : empty } catch (err) { return empty } }
const items = parse(row.batchJson, [])
const outcomes = parse(row.outcomesJson, {})
items.forEach((item, index) => {
    const name = item && item.itemId != null && String(item.itemId) !== '' ? String(item.itemId) : `#${index + 1}`
    outcomeList.push(Object.assign({itemId: name}, outcomes[name] || {outcome: 'waiting', reasonCode: null}))
})

outcomeList = []; acceptedCount = 0
ec.artifactExecution.disableAuthz()
const row = ec.entity.find('moqui.chat.ChatBridgeInbound').condition('chatBridgeId', chatBridgeId).condition('transactionId', transactionId).one()
if (!row) return
const parse = (text, empty) => { try { return text ? JSON.parse(text) : empty } catch (err) { return empty } }
const items = parse(row.batchJson, [])
const outcomes = parse(row.outcomesJson, {})
const now = nowMillis != null ? Number(nowMillis) : Number(ec.user.nowTimestamp)
const nameOf = (item, index) => item && item.itemId != null && String(item.itemId) !== '' ? String(item.itemId) : `#${index + 1}`
for (let pass = 0; pass < 3; pass++) {
    let mapped = 0, waiting = 0
    items.forEach((item, index) => {
        const name = nameOf(item, index)
        const before = outcomes[name]
        if (before && before.outcome !== 'waiting') return
        let result = null
        ec.message.pushErrors()
        try {
            result = ec.service.sync().name('org.moqui.impl.ChatBridgeServices.process#InboundItem').parameters({chatBridgeId: chatBridgeId,
                item: item && typeof item === 'object' ? item : {}}).requireNewTransaction(true).call()
            if (ec.message.hasError()) result = {outcome: 'rejected', reasonCode: 'refused', message: ec.message.errorsString}
        } catch (err) {
            result = {outcome: 'rejected', reasonCode: 'failed', message: String(err && err.message ? err.message : err)}
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
        result = {outcome: result?.outcome || 'rejected', reasonCode: result?.reasonCode ?? null, message: result?.message ?? null,
            eventSeq: result?.eventSeq ?? null}
        if (result.outcome === 'rejected') ec.logger.warn(`Chat bridge ${chatBridgeId} transaction ${transactionId} item ${name}: ${result.reasonCode} ${result.message || ''}`)
        if (result.outcome === 'waiting' && now - Number(row.receivedDate) > 86400000)
            result = {outcome: 'rejected', reasonCode: 'targetMissing', message: 'What it is about never arrived', eventSeq: null}
        if (result.outcome === 'accepted') { mapped++; acceptedCount++ }
        if (result.outcome === 'waiting') waiting++
        outcomes[name] = result
    })
    if (!mapped || !waiting) break
}
const waitingCount = Object.values(outcomes).filter((outcome) => outcome.outcome === 'waiting').length
ec.service.sync().name('org.moqui.impl.ChatBridgeServices.update#InboundOutcomes').parameters({chatBridgeId: chatBridgeId,
    transactionId: transactionId, outcomesJson: JSON.stringify(outcomes), waitingCount: waitingCount}).requireNewTransaction(true).call()
items.forEach((item, index) => { const name = nameOf(item, index); outcomeList.push(Object.assign({itemId: name}, outcomes[name])) })
if (followUp && acceptedCount) ec.service.sync().name('org.moqui.impl.ChatBridgeServices.process#PendingInbound').parameters({
    chatBridgeId: chatBridgeId, excludeTransactionId: transactionId, nowMillis: now, waitingOnly: true}).call()

const row = ec.entity.find('moqui.chat.ChatBridgeInbound').condition('chatBridgeId', chatBridgeId).condition('transactionId', transactionId)
        .forUpdate(true).disableAuthz().one()
if (!row) return
const parse = (text, empty) => { try { const value = text ? JSON.parse(text) : empty; return value && typeof value === 'object' ? value : empty } catch (err) { return empty } }
const kept = parse(row.outcomesJson, {})
const given = parse(outcomesJson, {})
const FIRM = ['accepted', 'duplicate', 'echo', 'stale']
const merged = Object.assign({}, kept)
for (const [name, outcome] of Object.entries(given)) {
    const before = kept[name]
    if (before && before.outcome !== 'waiting' && (outcome?.outcome === 'waiting' || (FIRM.includes(before.outcome) && !FIRM.includes(outcome?.outcome)))) continue
    merged[name] = outcome
}
const items = parse(row.batchJson, [])
const nameOf = (item, index) => item && item.itemId != null && String(item.itemId) !== '' ? String(item.itemId) : `#${index + 1}`
const waiting = Array.isArray(items) ? items.filter((item, index) => (merged[nameOf(item, index)]?.outcome || 'waiting') === 'waiting').length
        : Object.values(merged).filter((outcome) => outcome?.outcome === 'waiting').length
const fields = {outcomesJson: JSON.stringify(merged), waitingCount: waiting, statusEnumId: waiting > 0 ? 'CbiWaiting' : 'CbiDone',
    processedDate: ec.user.nowTimestamp}
if (!waiting && Array.isArray(items)) fields.batchJson = JSON.stringify(items.map((item, index) => ({itemId: nameOf(item, index)})))
row.setFields(fields, true, null, null)
row.update()

processedCount = 0
ec.artifactExecution.disableAuthz()
const now = nowMillis != null ? Number(nowMillis) : Number(ec.user.nowTimestamp)
const cf = ec.entity.conditionFactory
let find = ec.entity.find('moqui.chat.ChatBridgeInbound')
if (waitingOnly) find = find.condition('statusEnumId', 'CbiWaiting')
else find = find.condition(cf.makeCondition([cf.makeCondition('statusEnumId', 'equals', 'CbiWaiting'),
    cf.makeCondition([cf.makeCondition('statusEnumId', 'equals', 'CbiReceived'),
        cf.makeCondition('receivedDate', 'less', new Date(now - 60000))], 'and')], 'or'))
if (chatBridgeId) find = find.condition('chatBridgeId', chatBridgeId)
const rows = Array.from(find.selectField('chatBridgeId').selectField('transactionId').orderBy('receivedDate').limit(200).list())
// a disabled bridge takes no input: its batches wait until it is enabled again
const disabled = new Set(Array.from(ec.entity.find('moqui.chat.ChatBridge').condition('statusId', 'CbsDisabled').selectField('chatBridgeId')
        .list()).map((bridge) => bridge.chatBridgeId))
for (const row of rows) {
    if (excludeTransactionId && row.chatBridgeId === chatBridgeId && row.transactionId === excludeTransactionId) continue
    if (disabled.has(row.chatBridgeId)) continue
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.impl.ChatBridgeServices.process#Inbound').parameters({chatBridgeId: row.chatBridgeId,
            transactionId: row.transactionId, nowMillis: now}).call()
        if (ec.message.hasError()) ec.logger.error(`Chat bridge ${row.chatBridgeId} transaction ${row.transactionId}: ${ec.message.errorsString}`)
        else processedCount++
    } catch (err) {
        ec.logger.error(`Chat bridge ${row.chatBridgeId} transaction ${row.transactionId}: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

outcome = 'rejected'; reasonCode = null; message = null; eventSeq = null
ec.artifactExecution.disableAuthz()
const reject = (code, text) => { outcome = 'rejected'; reasonCode = code; message = text }
const TYPES = ['message', 'edit', 'reaction', 'redaction']
const field = (name, max) => {
    const value = item[name]
    if (value == null || value === '') return null
    const text = String(value)
    return text.length <= (max || 255) ? text : undefined
}
const type = field('type', 32)
const externalRoomId = field('externalRoomId'), externalEventId = field('externalEventId'), externalUserId = field('externalUserId')
const displayName = field('displayName'), avatarUrl = field('avatarUrl', 1024), relatesTo = field('relatesToExternalEventId')
const text = field('text', 65536), key = field('key', 64), replyTo = field('replyToExternalEventId')
if (!TYPES.includes(type)) { reject('malformed', 'An item is a message, edit, reaction or redaction'); return }
if (!externalRoomId || !externalEventId || !externalUserId) { reject('malformed', 'An item names its room, its event and its sender'); return }
if ([displayName, avatarUrl, relatesTo, text, key, replyTo].some((value) => value === undefined)) { reject('malformed', 'A field of the item is too long'); return }
if (item.attachments != null && Array.from(item.attachments || []).length) { reject('attachmentsUnsupported', 'Files from a bridge are not taken yet'); return }
if ((type === 'message' || type === 'edit') && !(text && text.trim())) { reject('malformed', 'A message or edit has text'); return }
if (type !== 'message' && !relatesTo) { reject('malformed', 'An edit, reaction or redaction names what it is about'); return }
if (type === 'reaction' && (!key || Array.from(key).length > 32 || /[<>]/.test(key))) { reject('malformed', 'A reaction is an emoji or a short word'); return }
const originMillis = item.originDate != null && !Number.isNaN(Number(item.originDate)) ? Number(item.originDate) : null
const now = ec.user.nowTimestamp

const mapping = Array.from(ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatBridgeId', chatBridgeId)
        .condition('externalRoomId', externalRoomId).condition('thruDate', null).list())[0]
if (!mapping) { reject('noMapping', 'The room is not mapped to a local room'); return }
if (mapping.directionEnumId === 'CrbOut') { reject('notInbound', 'The room takes nothing in from this bridge'); return }
const chatRoomId = mapping.chatRoomId
const known = ec.entity.find('moqui.chat.ChatEventExternal').condition('chatBridgeId', chatBridgeId).condition('externalRoomId', externalRoomId)
        .condition('externalEventId', externalEventId).one()
if (known) { outcome = known.originEnumId === 'CeoOutbound' ? 'echo' : 'duplicate'; eventSeq = known.eventSeq ?? null; return }

// what an edit, reaction or delete is about: it waits for its mapping
let target = null
if (type !== 'message') {
    target = ec.entity.find('moqui.chat.ChatEventExternal').condition('chatBridgeId', chatBridgeId).condition('externalRoomId', externalRoomId)
            .condition('externalEventId', relatesTo).one()
    if (!target || target.eventSeq == null) { outcome = 'waiting'; return }
}

// the sender: its external user and actor, and a member of the room. A new one is made under the bridge's row lock,
// looked for again, so two batches of one new person at once make one (a lock on a missing row locks nothing)
const findExternal = () => Array.from(ec.entity.find('moqui.chat.ChatExternalUser').condition('chatBridgeId', chatBridgeId)
        .condition('externalUserId', externalUserId).list())[0]
let externalUser = findExternal()
if (!externalUser) {
    ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', chatBridgeId).selectField('chatBridgeId').forUpdate(true).one()
    externalUser = findExternal()
}
if (!externalUser) {
    externalUser = ec.entity.makeValue('moqui.chat.ChatExternalUser')
    externalUser.setSequencedIdPrimary()
    externalUser.setFields({chatBridgeId: chatBridgeId, externalUserId: externalUserId, displayName: displayName,
        avatarUrl: avatarUrl, createdDate: now}, true, null, null)
    externalUser.create()
} else if ((displayName && displayName !== externalUser.displayName) || (avatarUrl && avatarUrl !== externalUser.avatarUrl)) {
    if (displayName) externalUser.set('displayName', displayName)
    if (avatarUrl) externalUser.set('avatarUrl', avatarUrl)
    externalUser.update()
}
let actor = Array.from(ec.entity.find('moqui.chat.ChatActor').condition('chatExternalUserId', externalUser.chatExternalUserId).list())[0]
if (!actor) {
    actor = ec.entity.makeValue('moqui.chat.ChatActor')
    actor.setSequencedIdPrimary()
    actor.setFields({kindEnumId: 'CakExternal', chatExternalUserId: externalUser.chatExternalUserId, createdDate: now}, true, null, null)
    actor.create()
}
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).one()
if (!room) { reject('noMapping', 'The mapped room is gone'); return }
if (room.archivedDate) { reject('archived', 'The room is archived'); return }
let member = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('chatActorId', actor.chatActorId).one()
if (member && member.leftDate) { reject('notMember', 'The sender was taken out of the room'); return }
if (!member) {
    // as add#Member: the room's row lock, then a look again, so two first items make one member
    ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).selectField('chatRoomId').forUpdate(true).one()
    member = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('chatActorId', actor.chatActorId).one()
}
if (!member) {
    member = ec.entity.makeValue('moqui.chat.ChatRoomMember')
    member.setFields({chatRoomId: chatRoomId, chatActorId: actor.chatActorId, userId: null, roleEnumId: 'CmrMember', joinedDate: now,
        lastReadEventSeq: Number(room.lastEventSeq || 0), notificationLevelEnumId: 'CnlNone', isPinned: 'N', isMuted: 'N'}, true, null, null)
    member.create()
    ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId, eventTypeEnumId: 'CetMembership',
        senderActorId: actor.chatActorId, content: {action: 'join', chatActorId: actor.chatActorId, external: true},
        sourceChatBridgeId: chatBridgeId}).call()
    if (ec.message.hasError()) return
}

// the mapping first: a second worker of the same item stops here, on the unique key
const external = ec.entity.makeValue('moqui.chat.ChatEventExternal')
external.setSequencedIdPrimary()
external.setFields({chatRoomId: chatRoomId, chatBridgeId: chatBridgeId, chatRoomBridgeId: mapping.chatRoomBridgeId,
    externalRoomId: externalRoomId, externalEventId: externalEventId, originEnumId: 'CeoInbound',
    originDate: originMillis != null ? new Date(originMillis) : now,
    metadataJson: item.metadata ? JSON.stringify(item.metadata).slice(0, 4000) : null, createdDate: now}, true, null, null)
external.create()

const common = {chatRoomId: chatRoomId, senderActorId: actor.chatActorId, sourceChatBridgeId: chatBridgeId}
const escape = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const htmlOf = (value) => '<p>' + escape(value.trim()).replace(/\r?\n/g, '<br>') + '</p>'
let out = null
if (type === 'message') {
    let replyToEventSeq = null
    if (replyTo) {
        const replied = ec.entity.find('moqui.chat.ChatEventExternal').condition('chatBridgeId', chatBridgeId).condition('externalRoomId', externalRoomId)
                .condition('externalEventId', replyTo).one()
        if (replied && replied.eventSeq != null) replyToEventSeq = Number(replied.eventSeq)
    }
    out = ec.service.sync().name('org.moqui.impl.ChatServices.send#Message').parameters(Object.assign({body: htmlOf(text),
        replyToEventSeq: replyToEventSeq}, common)).call()
    if (ec.message.hasError()) return
    eventSeq = out.eventSeq
} else {
    const targetEvent = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', target.eventSeq).one()
    if (!targetEvent) { reject('noMapping', 'What it is about is gone'); return }
    if (type === 'edit') {
        // an edit older than the last one applied changes nothing
        if (originMillis != null && target.lastEditOriginDate != null && originMillis <= Number(target.lastEditOriginDate)) {
            outcome = 'stale'; return }
        if (targetEvent.senderActorId !== actor.chatActorId) { reject('notOwn', 'Only its sender edits a message'); return }
        out = ec.service.sync().name('org.moqui.impl.ChatServices.edit#Message').parameters(Object.assign({eventSeq: Number(target.eventSeq),
            body: htmlOf(text)}, common)).call()
        if (ec.message.hasError()) return
        eventSeq = out.editEventSeq
        target.set('lastEditOriginDate', originMillis != null ? new Date(originMillis) : now)
        target.update()
    } else if (type === 'reaction') {
        out = ec.service.sync().name('org.moqui.impl.ChatServices.react#Message').parameters(Object.assign({eventSeq: Number(target.eventSeq),
            key: key, mode: 'add'}, common)).call()
        if (ec.message.hasError()) return
        eventSeq = out.reactionEventSeq
    } else if (targetEvent.eventTypeEnumId === 'CetReaction') {
        // a reaction taken back
        if (targetEvent.senderActorId !== actor.chatActorId) { reject('notOwn', 'Only its sender takes a reaction back'); return }
        let reactionKey = null
        try { reactionKey = JSON.parse(targetEvent.contentJson || '{}').key } catch (err) { reactionKey = null }
        out = ec.service.sync().name('org.moqui.impl.ChatServices.react#Message').parameters(Object.assign({
            eventSeq: Number(targetEvent.relatesToEventSeq), key: reactionKey, mode: 'remove'}, common)).call()
        if (ec.message.hasError()) return
        eventSeq = out.reactionEventSeq
    } else {
        if (targetEvent.senderActorId !== actor.chatActorId) { reject('notOwn', 'Only its sender deletes a message'); return }
        out = ec.service.sync().name('org.moqui.impl.ChatServices.redact#Message').parameters(Object.assign({eventSeq: Number(target.eventSeq)},
            common)).call()
        if (ec.message.hasError()) return
        eventSeq = out.redactionEventSeq
    }
}
if (eventSeq != null) { external.set('eventSeq', eventSeq); external.update() }
outcome = 'accepted'

deliveryMap = {}
const seqs = Array.from(new Set(Array.from(eventSeqList || []).map(Number).filter((seq) => !Number.isNaN(seq))))
if (!seqs.length) return
const rows = Array.from(ec.entity.find('moqui.chat.ChatBridgeDelivery').condition('chatRoomId', chatRoomId).condition('eventSeq', 'in', seqs)
        .disableAuthz().list())
if (!rows.length) return
const bridges = {}
for (const row of ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', 'in', Array.from(new Set(rows.map((row) => row.chatBridgeId))))
        .disableAuthz().list()) bridges[row.chatBridgeId] = row
const typeIds = Array.from(new Set(Object.values(bridges).map((row) => row.typeEnumId).filter((id) => id)))
const types = {}
if (typeIds.length) for (const row of ec.entity.find('moqui.basic.Enumeration').condition('enumId', 'in', typeIds).disableAuthz().list()) types[row.enumId] = row
const STATE = {CdsPending: 'pending', CdsAccepted: 'accepted', CdsFailed: 'failed', CdsUncertain: 'uncertain'}
const RANK = {failed: 4, uncertain: 3, pending: 2, accepted: 1}
for (const row of rows) {
    const state = STATE[row.statusEnumId] || 'pending'
    const bridge = bridges[row.chatBridgeId] || {}
    const entry = deliveryMap[Number(row.eventSeq)] = deliveryMap[Number(row.eventSeq)] || {state: 'accepted', retryable: false, destinations: []}
    entry.destinations.push({chatBridgeDeliveryId: row.chatBridgeDeliveryId, chatBridgeId: row.chatBridgeId, bridgeName: bridge.name ?? null,
        networkName: types[bridge.typeEnumId]?.description || null, state: state, reasonCode: row.reasonCode ?? null,
        error: row.lastErrorText ?? null, attemptCount: Number(row.attemptCount || 0), retryable: state === 'failed' || state === 'uncertain'})
    if (RANK[state] > RANK[entry.state]) entry.state = state
    if (state === 'failed' || state === 'uncertain') entry.retryable = true
}

const deliveries = ec.service.sync().name('org.moqui.impl.ChatBridgeServices.get#EventDeliveries').parameters({chatRoomId: chatRoomId,
    eventSeqList: [eventSeq]}).call()?.deliveryMap || {}
const delivery = deliveries[eventSeq] || deliveries[String(eventSeq)] || null
ec.service.sync().name('org.moqui.impl.ChatServices.push#Update').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    fields: {delivery: delivery}}).disableAuthz().call()

reasonCode = null
const row = ec.entity.find('moqui.chat.ChatBridgeDelivery').condition('chatBridgeDeliveryId', chatBridgeDeliveryId).disableAuthz().one()
const admin = ec.user.hasPermission('ChatBridgeAdmin')
const access = row ? ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', row.chatRoomId).call() : null
if (!row || (!admin && !access?.canRead)) { reasonCode = 'notFound'; ec.message.addError('Delivery not found'); return }
const event = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', row.chatRoomId).condition('eventSeq', row.eventSeq).disableAuthz().one()
const own = !!event && !!event.senderUserId && event.senderUserId === ec.user.userId && !!access?.isMember
if (!admin && !own && !access?.canModerate) { reasonCode = 'notAllowed'; ec.message.addError(ec.l10n.localize('Only the sender or a moderator sends it again')); return }
if (!['CdsFailed', 'CdsUncertain'].includes(row.statusEnumId)) { reasonCode = 'notRetryable'; ec.message.addError(ec.l10n.localize('Only a failed or uncertain delivery is sent again')); return }
ec.entity.find('moqui.chat.ChatBridgeDelivery').condition('chatBridgeDeliveryId', chatBridgeDeliveryId)
        .condition('statusEnumId', 'in', ['CdsFailed', 'CdsUncertain']).disableAuthz()
        .updateAll({statusEnumId: 'CdsPending', attemptCount: 0, nextAttemptDate: null, leaseOwner: null, leaseExpiresDate: null,
            reasonCode: null, lastErrorText: null})
ec.service.sync().name('org.moqui.impl.ChatServices.wake#BridgeDelivery').disableAuthz().call()
ec.service.sync().name('org.moqui.impl.ChatBridgeServices.push#DeliveryState').parameters({chatRoomId: row.chatRoomId,
    eventSeq: row.eventSeq}).disableAuthz().call()

bridgeList = []; problemList = []
if (!ec.user.hasPermission('ChatBridgeAdmin')) { ec.message.addError(ec.l10n.localize('Chat bridges are for administrators')); return }
const toMillis = (value) => value == null || value === '' ? null : Number(value)
const bridges = Array.from(ec.entity.find('moqui.chat.ChatBridge').orderBy('name').disableAuthz().list())
const ids = bridges.map((row) => row.chatBridgeId)
const types = {}, statuses = {}
for (const row of ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'ChatBridgeType').disableAuthz().list()) types[row.enumId] = row
for (const row of ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId', 'ChatBridge').disableAuthz().list()) statuses[row.statusId] = row
const caps = ids.length ? ec.service.sync().name('org.moqui.impl.ChatServices.get#BridgeCapabilities').parameter('chatBridgeIdList', ids)
        .disableAuthz().call()?.capabilityMap || {} : {}
const count = (entity, conditions) => {
    let find = ec.entity.find(entity).disableAuthz()
    for (const [name, value] of Object.entries(conditions)) find = find.condition(name, value)
    return find.count()
}
for (const row of bridges) {
    const id = row.chatBridgeId
    bridgeList.push({chatBridgeId: id, name: row.name ?? null, typeEnumId: row.typeEnumId ?? null,
        networkName: types[row.typeEnumId]?.description || null, adapterName: row.adapterName || types[row.typeEnumId]?.enumCode || null,
        statusId: row.statusId ?? null, statusText: statuses[row.statusId]?.description || null, lastErrorText: row.lastErrorText ?? null,
        lastErrorDate: toMillis(row.lastErrorDate), lastStatusDate: toMillis(row.lastStatusDate), sendsPerMinute: row.sendsPerMinute ?? null,
        hasToken: !!row.inboundTokenHash, adapter: caps[id]?.adapter === true,
        roomCount: count('moqui.chat.ChatRoomBridge', {chatBridgeId: id, thruDate: null}),
        pendingCount: count('moqui.chat.ChatBridgeDelivery', {chatBridgeId: id, statusEnumId: 'CdsPending'}),
        failedCount: count('moqui.chat.ChatBridgeDelivery', {chatBridgeId: id, statusEnumId: 'CdsFailed'}),
        uncertainCount: count('moqui.chat.ChatBridgeDelivery', {chatBridgeId: id, statusEnumId: 'CdsUncertain'})})
}
const names = {}
for (const row of bridges) names[row.chatBridgeId] = row.name
const problems = Array.from(ec.entity.find('moqui.chat.ChatBridgeDelivery').condition('statusEnumId', 'in', ['CdsFailed', 'CdsUncertain'])
        .orderBy('-lastAttemptDate').limit(50).disableAuthz().list())
const roomNames = {}
const roomIds = Array.from(new Set(problems.map((row) => row.chatRoomId)))
if (roomIds.length) for (const row of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', roomIds).disableAuthz().list())
    roomNames[row.chatRoomId] = row.roomName || row.chatRoomId
for (const row of problems) problemList.push({chatBridgeDeliveryId: row.chatBridgeDeliveryId, chatBridgeId: row.chatBridgeId,
    bridgeName: names[row.chatBridgeId] || row.chatBridgeId, chatRoomId: row.chatRoomId, roomName: roomNames[row.chatRoomId] || row.chatRoomId,
    eventSeq: Number(row.eventSeq), state: row.statusEnumId === 'CdsFailed' ? 'failed' : 'uncertain', reasonCode: row.reasonCode ?? null,
    error: row.lastErrorText ?? null, attemptCount: Number(row.attemptCount || 0), lastAttemptDate: toMillis(row.lastAttemptDate)})

if (!ec.user.hasPermission('ChatBridgeAdmin')) { ec.message.addError(ec.l10n.localize('Chat bridges are for administrators')); return }
let row = chatBridgeId ? ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', chatBridgeId).disableAuthz().one() : null
if (chatBridgeId && !row) { ec.message.addError(`Chat bridge ${chatBridgeId} not found`); return }
if (!row && (!name || !typeEnumId)) { ec.message.addError(ec.l10n.localize('A bridge needs a name and a network')); return }
if (typeEnumId && !ec.entity.find('moqui.basic.Enumeration').condition('enumId', typeEnumId).condition('enumTypeId', 'ChatBridgeType').disableAuthz().one()) {
    ec.message.addError(`Unknown chat network ${typeEnumId}`); return }
if (configJson) { try { JSON.parse(configJson) } catch (err) { ec.message.addError(ec.l10n.localize('The configuration is not JSON')); return } }
const created = !row
if (!row) {
    row = ec.entity.makeValue('moqui.chat.ChatBridge')
    row.setSequencedIdPrimary()
    row.setFields({createdDate: ec.user.nowTimestamp, statusId: 'CbsNotConnected'}, true, null, null)
}
if (name) row.set('name', name)
if (typeEnumId) row.set('typeEnumId', typeEnumId)
if (adapterName != null) row.set('adapterName', adapterName || null)
if (configJson) row.set('configJson', configJson)
if (sendsPerMinute != null) row.set('sendsPerMinute', sendsPerMinute > 0 ? sendsPerMinute : null)
if (inboundToken) row.set('inboundTokenHash', ec.service.sync().name('org.moqui.impl.ChatBridgeServices.check#BridgeToken')
        .parameters({token: inboundToken, hashOnly: true}).call().tokenHash)
if (disabled === 'Y') row.set('statusId', 'CbsDisabled')
else if (disabled === 'N' && row.statusId === 'CbsDisabled') row.set('statusId', 'CbsNotConnected')
if (created) row.create(); else row.update()
chatBridgeId = row.chatBridgeId
ec.service.sync().name('org.moqui.impl.ChatServices.wake#BridgeDelivery').disableAuthz().call()

reasonCode = null
if (!ec.user.hasPermission('ChatBridgeAdmin')) { ec.message.addError(ec.l10n.localize('Chat bridges are for administrators')); return }
const DIRECTIONS = ['CrbBoth', 'CrbIn', 'CrbOut']
if (directionEnumId && !DIRECTIONS.includes(directionEnumId)) { ec.message.addError(`Unknown direction ${directionEnumId}`); return }
if (chatRoomBridgeId) {
    const row = ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomBridgeId', chatRoomBridgeId).disableAuthz().one()
    if (!row) { ec.message.addError(`Room mapping ${chatRoomBridgeId} not found`); return }
    if (externalRoomName != null) row.set('externalRoomName', externalRoomName || null)
    if (externalRoomUrl != null) row.set('externalRoomUrl', externalRoomUrl || null)
    if (directionEnumId) row.set('directionEnumId', directionEnumId)
    row.update()
    return
}
if (!chatRoomId || !chatBridgeId || !externalRoomId) { ec.message.addError(ec.l10n.localize('A mapping names a room, a bridge and the room there')); return }
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).disableAuthz().one()
if (!room) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (room.roomTypeEnumId === 'CrtDirect') { ec.message.addError(ec.l10n.localize('A direct conversation is not bridged')); return }
if (room.encrypted === 'Y') { reasonCode = 'encryptedRoom'; ec.message.addError(ec.l10n.localize('An encrypted room is not bridged: the server has no text to send')); return }
if (!ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', chatBridgeId).disableAuthz().one()) { ec.message.addError(`Chat bridge ${chatBridgeId} not found`); return }
ec.entity.find('moqui.chat.ChatBridge').condition('chatBridgeId', chatBridgeId).forUpdate(true).disableAuthz().one()
if (ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatBridgeId', chatBridgeId).condition('externalRoomId', externalRoomId)
        .condition('thruDate', null).disableAuthz().count()) {
    reasonCode = 'mappingExists'; ec.message.addError(ec.l10n.localize('That room of the network is mapped already')); return }
const row = ec.entity.makeValue('moqui.chat.ChatRoomBridge')
row.setSequencedIdPrimary()
row.setFields({chatRoomId: chatRoomId, chatBridgeId: chatBridgeId, externalRoomId: externalRoomId, externalRoomName: externalRoomName || null,
    externalRoomUrl: externalRoomUrl || null, directionEnumId: directionEnumId || 'CrbBoth', fromDate: ec.user.nowTimestamp}, true, null, null)
row.create()
chatRoomBridgeId = row.chatRoomBridgeId

if (!ec.user.hasPermission('ChatBridgeAdmin')) { ec.message.addError(ec.l10n.localize('Chat bridges are for administrators')); return }
ec.entity.find('moqui.chat.ChatRoomBridge').condition('chatRoomBridgeId', chatRoomBridgeId).condition('thruDate', null)
        .disableAuthz().updateAll({thruDate: ec.user.nowTimestamp})
